def duration(value):
    s=value.strip()
    if s=='0':return 0.0
    if not s:raise ValueError('value was empty')
    total=0; pos=0
    # Error offsets refer to byte positions in the untrimmed input.
    leading=len(value)-len(value.lstrip())
    def at(i): return len(value[:leading+i].encode())
    while pos<len(s):
        while pos<len(s) and s[pos].isspace():pos+=1
        if pos==len(s):break
        if not '0'<=s[pos]<='9':raise ValueError(f'expected number at {at(pos)}')
        start=pos
        while pos<len(s) and '0'<=s[pos]<='9':pos+=1
        integer=int(s[start:pos])
        if integer > 2**64-1:raise ValueError(TOO_LARGE)
        fraction=''
        if pos<len(s) and s[pos]=='.':
            dot=pos;pos+=1;start=pos
            while pos<len(s) and '0'<=s[pos]<='9':pos+=1
            if start==pos:raise ValueError(f'invalid character at {at(dot)}')
            fraction=s[start:pos]
        while pos<len(s) and s[pos].isspace():pos+=1
        start=pos
        while pos<len(s) and (s[pos].isascii() and s[pos].isalpha() or s[pos]=='µ'):pos+=1
        unit=s[start:pos]
        if pos<len(s) and not(s[pos].isspace() or '0'<=s[pos]<='9'):
            raise ValueError(f'invalid character at {at(pos)}')
        if not unit:
            raise ValueError(f'time unit needed, for example {integer}sec or {integer}ms')
        if unit not in UNITS:raise ValueError('unknown time unit "'+unit+'"'+UNKNOWN_UNIT)
        mul=UNITS[unit]
        n=integer*mul
        if fraction:
            den=10**len(fraction);num=int(fraction)*mul
            if num%den:raise ValueError(TOO_LARGE)
            n+=num//den
        total+=n
        if total > (2**64)*10**9-1:raise ValueError(TOO_LARGE)
    return total/1e9


def parse_value(o, val):
    if o.choices:
        if val=='':missing(o)
        if val not in o.choices:invalid(o,val)
        return val
    if o.name=='speed-factor':
        if not val:invalid(o,val,'cannot parse float from empty string')
        if not re.fullmatch(r'[+-]?(?:(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?|inf(?:inity)?|nan)',val,re.I):
            invalid(o,val,'invalid float literal')
        n=float(val)
        if n<.01:invalid(o,val,'Speed factor must be larger than 0.01')
        return n
    if o.name in ('instant-print-lines','exit-after-modules'):
        if not val:invalid(o,val,'cannot parse integer from empty string')
        if not re.fullmatch(r'\+?[0-9]+',val):invalid(o,val,'invalid digit found in string')
        n=int(val);maxval=(1<< (64 if o.name=='instant-print-lines' else 32))-1
        if n>maxval:invalid(o,val,'number too large to fit in target type')
