            fail(f"the argument '{o.full}' cannot be used multiple times",'[OPTIONS]')
        seen.add(o.name)
        if o.name=='help':output(help_text());raise SystemExit(0)
        if o.name=='version':output('genact '+VERSION+'\n');raise SystemExit(0)
        if o.value:val=parse_value(o,val)
        else:val=True
