"""Command-line parsing and user-facing documentation."""
import os
import re
import sys
import textwrap
from dataclasses import dataclass

MODULES = 'ansible bootlog botnet bruteforce cargo cc composer cryptomining docker_build docker_image_rm download julia kernel_compile memdump mkinitcpio rkhunter simcity terraform uv weblog wpt'.split()
SHELLS = 'bash elvish fish powershell zsh'.split()
VERSION = '1.5.1'
ABOUT = 'A nonsense activity generator'

@dataclass
class Option:
    name: str
    short: str
    value: str
    description: str
    default: str = ''
    choices: tuple = ()

    @property
    def full(self):
        return '--' + self.name + (' <' + self.value + '>' if self.value else '')

OPTIONS = [
    Option('list-modules','l','','List available modules'),
    Option('modules','m','MODULES','Run only these modules',choices=tuple(MODULES)),
    Option('speed-factor','s','SPEED_FACTOR','Global speed factor','1'),
    Option('instant-print-lines','i','INSTANT_PRINT_LINES','Instantly print this many lines','0'),
    Option('inhibit','','','Keep the computer awake and the display on while genact is running'),
    Option('exit-after-time','','EXIT_AFTER_TIME','Exit after running for this long (format example: 2h10min)'),
    Option('exit-after-modules','','EXIT_AFTER_MODULES','Exit after running this many modules'),
    Option('print-completions','','shell','Generate completion file for a shell',choices=tuple(SHELLS)),
    Option('print-manpage','','','Generate man page'),
    Option('help','h','','Print help'),
    Option('version','V','','Print version'),
]
BY_NAME = {o.name:o for o in OPTIONS}
BY_SHORT = {o.short:o for o in OPTIONS if o.short}
FOOTER = "For more information, try '--help'.\n"


def program_name():
    return os.path.basename(sys.argv[0]) or 'executable'


def output(text, file=sys.stdout):
    file.write(text)
    file.flush()


def help_text(width=None):
    if width is None:
        try: width = os.get_terminal_size(sys.stdout.fileno()).columns or 100
        except OSError: width = 100
    result = [ABOUT,'',f'Usage: {program_name()} [OPTIONS]','','Options:']
    # Once the descriptions cease to fit, all of them use a second line.
    max_flag = max(len('  '+('-'+o.short+', ' if o.short else '    ')+o.full) for o in OPTIONS)
    col = max_flag + 2
    longest = max(len(o.description + (' [default: '+o.default+']' if o.default else '') + (' [possible values: '+', '.join(o.choices)+']' if o.choices else '')) for o in OPTIONS)
    # The help layout has a quarter-page minimum description column.
    next_line = col <= width and (width - col) < width * .4
    for o in OPTIONS:
        flag = '  '+('-'+o.short+', ' if o.short else '    ')+o.full
        desc = o.description
        if o.default: desc += ' [default: '+o.default+']'
        if o.choices: desc += ' [possible values: '+', '.join(o.choices)+']'
        if next_line:
            result.append(flag)
            result.extend('          '+s for s in textwrap.wrap(desc,width=max(1,width-10),break_long_words=False,break_on_hyphens=False))
        else:
            wraps = textwrap.wrap(desc,width=max(1,width-col),break_long_words=False,break_on_hyphens=False)
            result.append(flag.ljust(col) + wraps[0])
            result.extend(' '*col+s for s in wraps[1:])
    return '\n'.join(result)+'\n'


def fail(message, usage=None, extra=''):
    s = 'error: '+message+'\n'
    if extra: s += extra
    s += '\n'
    if usage is not None: s += 'Usage: '+program_name()+' '+usage+'\n\n'
    s += FOOTER
    output(s,sys.stderr)
    raise SystemExit(2)


def jaro_winkler(a,b):
    if a == b: return 1.0
    if not a or not b: return 0.0
    window = max(len(a),len(b))//2 - 1
    used_a = [False]*len(a); used_b = [False]*len(b)
    matches=0
    for i,c in enumerate(a):
        for j in range(max(0,i-window),min(len(b),i+window+1)):
            if not used_b[j] and c == b[j]:
                used_a[i]=used_b[j]=True;matches+=1;break
    if not matches:return 0.0
    aa=[c for c,yes in zip(a,used_a) if yes]
    bb=[c for c,yes in zip(b,used_b) if yes]
    trans=sum(c!=d for c,d in zip(aa,bb))/2
    score=(matches/len(a)+matches/len(b)+(matches-trans)/matches)/3
    if score > .7:
        n=0
        for c,d in zip(a,b):
            if c!=d or n==4:break
            n+=1
        score+=n*.1*(1-score)
    return score


def suggest(value, choices):
    candidates = [(jaro_winkler(value,c),i,c) for i,c in enumerate(choices)]
    candidates = [x for x in candidates if x[0] > .8]
